CREATE TABLE IF NOT EXISTS mails (owner TEXT NOT NULL, id TEXT NOT NULL, thread TEXT NOT NULL DEFAULT '', sender TEXT NOT NULL DEFAULT '', addr TEXT NOT NULL DEFAULT '', subject TEXT NOT NULL DEFAULT '', date INTEGER NOT NULL DEFAULT 0, snippet TEXT NOT NULL DEFAULT '', folder TEXT NOT NULL DEFAULT '', trip TEXT NOT NULL DEFAULT '', important INTEGER NOT NULL DEFAULT 0, pushed INTEGER NOT NULL DEFAULT 0, fixed INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (owner, id));
CREATE INDEX IF NOT EXISTS mails_folder ON mails(owner, folder, date);
